function OUT = AF7R46_PRE_RUN_AUDIT()
clc; fprintf('\n====================================================================================================\n'); fprintf(' AF7R46A | LAST-TWO REALTIME PRE-RUN AUDIT\n'); fprintf('====================================================================================================\n');
src=which('REPLANNING_SYSTEM'); expected='890876116b4782725d8c337e53923a14892a9b5f4f00a0e7de030b9d4433c446'; h=sha256_file(src); assert(strcmp(h,expected)); raw=fileread(src); compact=regexprep(raw,'\s+','');
C=struct(); C.r45=contains(raw,'AF7R45-TWO-TRACK-RT'); C.r46=contains(raw,'AF7R46-COMPACT-COMMIT'); C.compact_callback=contains(raw,'af7r46_single_core_proposal_compact'); C.same_mex=contains(raw,'RAW=af7r36_single_core_mex(1,pkt);'); C.defer_eval=contains(raw,'af7r46_materialize_candidate_evaluators'); C.fast_packet=contains(raw,'prepare_obstacle_packet_fast_target'); C.pre_mutation_deadline=contains(raw,'REFERENCE_ONLY_COMMIT_PREPARATION_DEADLINE_EXCEEDED'); C.observer_cache=contains(raw,'observer_prepare_static_setup_cache'); C.observer_math=contains(raw,'observer_contract_two_events(I.previous_measurement,C,F,xhat)'); C.sensor_memory=contains(raw,'apply_simulated_sensor_memory'); C.hard4ms=contains(raw,'hard_modify_deadline_s<=4.0e-3'); C.r9=contains(raw,'R9_LOCAL_VECTOR_COUPLED_ADAPTIVE_BERNSTEIN_FLATNESS_SPEED'); C.wholebody=contains(raw,'MIDPOINT_STATIC_SUPPORT_MINUS_SPEED_TIMES_HALFWIDTH'); C.sampled_true=contains(compact,[char(39) 'sampled_acceptance' char(39) ',true']);
mc=meta.class.fromName('REPLANNING_SYSTEM'); assert(~isempty(mc)); closed=C.r45&&C.r46&&C.compact_callback&&C.same_mex&&C.defer_eval&&C.fast_packet&&C.pre_mutation_deadline&&C.observer_cache&&C.observer_math&&C.sensor_memory&&C.hard4ms&&C.r9&&C.wholebody&&~C.sampled_true;
F=fieldnames(C); for k=1:numel(F), fprintf(' %-44s = %d\n',strrep(F{k},'_',' '),logical(C.(F{k}))); end; fprintf(' source SHA-256                           = %s\n',h); fprintf(' AF7R46 pre-run closed                    = %d\n',closed); fprintf('====================================================================================================\n'); OUT=struct('schema','AF7R46A_PRE_RUN_AUDIT_V1','closed',closed,'checks',C,'sha256',h); assignin('base','AF7R46_PRE_RUN_AUDIT_OUT',OUT);
end
function h=sha256_file(fp)
fid=fopen(fp,'rb'); assert(fid>=0); c=onCleanup(@()fclose(fid)); b=fread(fid,Inf,'*uint8'); clear c; md=java.security.MessageDigest.getInstance('SHA-256'); md.update(b); d=typecast(md.digest(),'uint8'); h=lower(reshape(dec2hex(d,2).',1,[]));
end
